//! Empirical validation of the bounded-memory (external-bucketing) bulk
//! build's central claim: peak build RSS should scale with the caller's
//! `BulkBuildBudget`, not with the input triple count N -- see
//! `BulkBuildBudget`'s own doc comment in
//! `radixtree_dfs_interleaved_varskip_unrolled_generic.rs` for the
//! O(budget)-not-O(N) accounting this measures directly.
//!
//! Unlike every other `rss_*.rs` binary in this project, the input
//! dataset here is generated by a genuinely streaming `Iterator`
//! ([`StreamingUniform`]) rather than a materialized `Vec<Triple>` --
//! holding the whole input in RAM first would itself reintroduce an O(N)
//! cost this binary exists to prove is no longer necessary, defeating
//! the measurement before the tree build even starts. This is also why
//! this binary generates its own dataset instead of reusing
//! `common::insertable_bench::large_scale_scenario` (fixed at a single
//! N=20,000,000): the whole point here is sweeping N at a *fixed*
//! budget.
//!
//! Usage: `cargo run --release --example rss_file_bounded_generic [num_triples] [budget_points]`
//! (defaults: 20,000,000 triples, budget 2,000,000 points). Run at
//! several N with the same budget, e.g.:
//! ```sh
//! for n in 5000000 10000000 20000000 40000000; do
//!     cargo run --release --example rss_file_bounded_generic "$n" 2000000
//! done
//! ```
//! and confirm peak RSS stays roughly flat across N instead of growing
//! linearly with it.

#[path = "common/mod.rs"]
mod common;

use common::metrics::{current_rss_kb, human_bytes, peak_rss_kb, MemSize};
use common::radixtree_dfs_interleaved_varskip_unrolled_generic::{BulkBuildBudget, File as GenericFile};
use common::rdf_gen::{SplitMix64, Triple};

const NUM_S: u32 = 2_000_000;
const NUM_P: u32 = 19;
const NUM_O: u32 = 2_000_000;
const BLOCK_CAPACITY: usize = 65536;

/// Generates `remaining` uniformly-random triples on the fly -- never
/// materializes them as a `Vec`, so this binary's own dataset generation
/// costs O(1) RAM regardless of `remaining`, the same property the
/// bounded-build path itself is being measured for.
struct StreamingUniform {
    rng: SplitMix64,
    remaining: usize,
}

impl Iterator for StreamingUniform {
    type Item = Triple;
    fn next(&mut self) -> Option<Triple> {
        if self.remaining == 0 {
            return None;
        }
        self.remaining -= 1;
        Some((self.rng.next_range(NUM_S as u64) as u32, self.rng.next_range(NUM_P as u64) as u32, self.rng.next_range(NUM_O as u64) as u32))
    }
}

fn main() {
    let mut args = std::env::args().skip(1);
    let num_triples: usize = args.next().and_then(|s| s.parse().ok()).unwrap_or(20_000_000);
    let budget_points: usize = args.next().and_then(|s| s.parse().ok()).unwrap_or(2_000_000);

    println!("=== bounded build: {num_triples} streaming triples, budget={budget_points} points, structure=generic(file), cap={BLOCK_CAPACITY} ===");

    let source = StreamingUniform { rng: SplitMix64::new(0xB0DED ^ num_triples as u64), remaining: num_triples };
    let dimension_sizes = [NUM_S as u64, NUM_P as u64, NUM_O as u64];
    let budget = BulkBuildBudget::new(budget_points);

    let t0 = std::time::Instant::now();
    let tree = GenericFile::build_dynamic_bounded(source, dimension_sizes, BLOCK_CAPACITY, budget);
    let build_time = t0.elapsed();
    let build_peak_rss = peak_rss_kb();
    let mem = tree.mem_size_bytes();
    let disk = tree.disk_bytes();
    let steady_rss = current_rss_kb();

    println!(
        "  build={build_time:>10.2?} mem_size_bytes(RAM)={:>10} disk={:>10} node_words={} blocks={}",
        human_bytes(mem),
        human_bytes(disk as usize),
        tree.node_word_count(),
        tree.block_count()
    );
    match build_peak_rss {
        Some(kb) => println!("  peak RSS immediately after build (VmHWM) = {} ({kb} KiB)", human_bytes(kb as usize * 1024)),
        None => println!("  peak RSS unavailable (non-Linux or /proc/self/status unreadable)"),
    }
    match steady_rss {
        Some(kb) => println!("  steady-state RSS (VmRSS, post-build) = {} ({kb} KiB)", human_bytes(kb as usize * 1024)),
        None => println!("  steady-state RSS unavailable (non-Linux or /proc/self/status unreadable)"),
    }
}
